//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			PulseData                                                                                                                                                                                                                                                                      
//	CREATOR:		Helgevold - Daniel Årvik                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE				  SIGN							DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0					2025-03-10		  Daniel Årvik			    Initial release
//	1.0.1					2025-09-08		  William Veim			    Rework initialising variables
//	1.1.0					2026-04-29		  William Veim			    Added input and logic for process TAG
//
//===============================================================================================================================
//
//		BESKRIVELSE:
//		Puls for akkumulering av data. Mengde per puls spesifiserers, data akkumuleres i dag, uke, måned, år.
//
//===============================================================================================================================

(*************************************************************************
 *	IMPORTING SYSTEM VARIABLES
 *************************************************************************)
 
DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct);

(*************************************************************************
 *	INITIALISING VARIABELS
 *************************************************************************)

Ext_AccumulatedData.EXT_General.Process_TAG:= Cfg_ProcessTAG;
EXT_AccumulatedData.EXT_Engineering.ConversationFactor_Visible:=TRUE; //Visible when puls data is used

IF NOT EXT_AccumulatedData.INT_Data.Initialise THEN
	
	//Engeneering parameter
	EXT_AccumulatedData.EXT_Engineering.ConversationFactor:=1;
	EXT_AccumulatedData.EXT_Engineering.Unit:='m3';

	//Init complete
	EXT_AccumulatedData.INT_Data.Initialise:=TRUE;

END_IF;

//Initialise reset date on first pulse input
IF EXT_AccumulatedData.EXT_Engineering.ResetDate_Total = '' AND RE_PulseIn.Q THEN
	
	EXT_AccumulatedData.EXT_Engineering.ResetDate_Total:=DateToString(DT_TO_DATE(GetTime()));
	
END_IF;	
	
(*************************************************************************
 *	INCREMENT AND DATA CONTROL
 *************************************************************************)
 
RE_PulseIn(Clk:=Inp_Pulse);


IF RE_PulseIn.Q THEN
	
	EXT_AccumulatedData.EXT_Statistics.Total_Today := EXT_AccumulatedData.EXT_Statistics.Total_Today + EXT_AccumulatedData.EXT_Engineering.ConversationFactor;
	EXT_AccumulatedData.EXT_Statistics.Total_Week := EXT_AccumulatedData.EXT_Statistics.Total_Week + EXT_AccumulatedData.EXT_Engineering.ConversationFactor;
	EXT_AccumulatedData.EXT_Statistics.Total_Month := EXT_AccumulatedData.EXT_Statistics.Total_Month + EXT_AccumulatedData.EXT_Engineering.ConversationFactor;
	EXT_AccumulatedData.EXT_Statistics.Total_Year := EXT_AccumulatedData.EXT_Statistics.Total_Year + EXT_AccumulatedData.EXT_Engineering.ConversationFactor;
	EXT_AccumulatedData.EXT_Statistics.Total := EXT_AccumulatedData.EXT_Statistics.Total + EXT_AccumulatedData.EXT_Engineering.ConversationFactor;
	
END_IF;

(*************************************************************************
 *	DATA RESET
 *************************************************************************)

//Reset total (manual reset)
IF EXT_AccumulatedData.EXT_Engineering.Reset_Toal THEN
	Clear(EXT_AccumulatedData.EXT_Statistics.Total);
	EXT_AccumulatedData.EXT_Engineering.ResetDate_Total:=DateToString(DT_TO_DATE(GetTime()));
	EXT_AccumulatedData.EXT_Engineering.Reset_Toal:=FALSE;
END_IF;

//Checks if new day
IF Sample_Day <> DateStruct.Day THEN
	EXT_AccumulatedData.EXT_Statistics.Total_Yesterday := EXT_AccumulatedData.EXT_Statistics.Total_Today;
	Clear(EXT_AccumulatedData.EXT_Statistics.Total_Today);
END_IF;

//Checks if new week
IF Sample_Week <> GetWeekOfYear(In:=GetTime()) THEN
	Clear(EXT_AccumulatedData.EXT_Statistics.Total_Week);
END_IF;

//Checks if new month
IF Sample_Month <> DateStruct.Month THEN
	Clear(EXT_AccumulatedData.EXT_Statistics.Total_Month);
END_IF;
			
//Checks if new year
IF GetWeekOfYear(In:=GetTime()) = 1 AND Sample_Week <> GetWeekOfYear(In:=GetTime()) THEN
	Clear(EXT_AccumulatedData.EXT_Statistics.Total_Year);
END_IF;

// Sampler
Sample_Day := DateStruct.Day;
Sample_Week := GetWeekOfYear(In:=GetTime());
Sample_Month := DateStruct.Month;
